  "verdict": "cleared",
  "finding_class": "none",
  "rationale": "The national split is not materially overstated. Indonesian banking usage strongly supports setoran tunai, while Malaysian banking sources use deposit tunai. Deposit tunai is attested in Indonesian contexts but is less clearly the ordinary account-funding term and may also denote a security deposit. The English cue and sense are accurate, both answers are semantically valid, the relation different-common-word is defensible, and no material false-friend error is present.",
  "claim_reviews": [
    {
      "subject": "English cue and sense",
      "conclusion": "Cash deposit correctly denotes money paid into an account in cash.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.bi.go.id/id/fungsi-utama/sistem-pembayaran/ritel/kanal-layanan/qris/qris-tuntas/default.aspx",
        "https://www.bankmandiri.co.id/en/livin/edukasi/cara-setor-tunai-tanpa-kartu"
      ]
    },
    {
      "subject": "Indonesian answer: setoran tunai",
      "conclusion": "Setoran tunai is an ordinary and institutionally supported Indonesian banking expression for a cash deposit.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.ojk.go.id/id/regulasi/Documents/Pages/Layanan-Keuangan-Tanpa-Kantor-dalam-Rangka-Keuangan-Inklusif-/POJK%201%20-%2003%20-%202022.pdf",
        "https://www.bankmandiri.co.id/en/livin/edukasi/cara-setor-tunai-tanpa-kartu",
        "https://www.bi.go.id/id/fungsi-utama/sistem-pembayaran/ritel/kanal-layanan/qris/qris-tuntas/default.aspx"
      ]
    },
    {
      "subject": "Malaysian answer: deposit tunai",
      "conclusion": "Deposit tunai is a normal Malaysian banking expression for cash deposited into a savings or current account.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.bankislam.com/wp-content/uploads/Agent-Banking-Term-Sheet-2.pdf",
        "https://www.maybank2u.com.my/iwov-resources/pdf/personal/services/agent-banking/agent-banking-depo-win-tnc-bm.pdf",
        "https://museum.bnm.gov.my/Fintech/360vr/files/02evolution/EVOLUTION%20IN%20MALAYSIA.pdf"
      ]
    },
    {
      "subject": "National split and overlap",
      "conclusion": "The split remains useful: the forms are not interchangeable ordinary preferences across the two varieties, although deposit tunai is attested in Indonesian contexts. This overlap does not materially invalidate different-common-word.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.ojk.go.id/id/regulasi/Documents/Pages/Layanan-Keuangan-Tanpa-Kantor-dalam-Rangka-Keuangan-Inklusif-/POJK%201%20-%2003%20-%202022.pdf",
        "https://www.bankislam.com/wp-content/uploads/Agent-Banking-Term-Sheet-2.pdf",
        "https://www.maybank2u.com.my/iwov-resources/pdf/personal/services/agent-banking/agent-banking-depo-win-tnc-bm.pdf"
      ]
    },
    {
      "subject": "False-friend contrast",
      "conclusion": "No material false-friend problem is present. Indonesian deposit tunai can occur in other senses, including security deposits, while Malaysian deposit has the standard banking sense; however, the learner's Indonesian answer avoids that ambiguity.",
      "material_risk": false,
      "evidence_refs": [
        "https://jdih.kemenkeu.go.id/api/download/fulltext/2018/128TAHUN2018PERPRES.pdf",
        "https://prpm.dbp.gov.my/Cari1?d=54140&keyword=deposit"
      ]
    }
  ]
}
